 var target=String(b.target||'').toLowerCase(),action=String(b.action||''),args=b.arguments&&typeof b.arguments==='object'&&!Array.isArray(b.arguments)?b.arguments:{},mode=String(b.mode||'observation').toLowerCase(),detail=String(b.detail||'summary');
 if(!/^[a-z][a-z0-9_-]{1,31}$/.test(target)||!/^[a-z][a-z0-9_.-]{2,95}$/i.test(action))return cb(new Error('ADMIN_CONSOLE_COMMAND_INVALID'));
 if(['summary','analysis','evidence'].indexOf(detail)<0)detail='summary';
 var requiredMode=ADMIN_CONSOLE.modeForAction(action);
 if(requiredMode==='forbidden')return cb(new Error('ADMIN_CONSOLE_COMMAND_FORBIDDEN'));
 if(requiredMode==='command'&&mode!=='command')return cb(Object.assign(new Error('COMMAND_MODE_REQUIRED'),{statusCode:409}));
