 var started=Date.now();
 function done(e,o,requestId){var dur=Date.now()-started;if(e){ADMIN_CONSOLE.audit('target='+target+' action='+action+' status=ERROR duration_ms='+dur+' error='+e.message);return cb(e);}ADMIN_CONSOLE.audit('target='+target+' action='+action+' status=OK duration_ms='+dur+' request_id='+(requestId||'-'));cb(null,{ok:true,protocol:'CP/1',target:target,action:action,mode:requiredMode,request_id:requestId||null,duration_ms:dur,response:o});}
 if(target==='server')return ADMIN_CONSOLE.executeServer(action,args,function(e,o){done(e,o,'admin-'+Date.now().toString(36));});
 if(target==='router')return adminConsoleRouterAction(action,args,function(e,o){done(e,o,'router-'+Date.now().toString(36));});
